using CustomCodeFramework.Core.Results;using CustomCodeFramework.Cqrs.Commands;using CustomCodeFramework.Persistence.Abstractions;using Dhole.Content.Application.Abstractions.Auditing;using Dhole.Content.Application.Abstractions.Cache;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Auditing;using Dhole.Content.Domain.Shared;namespace Dhole.Content.Application.ContentItems.UnpublishContent;public sealed class UnpublishContentCommandHandler(IContentItemRepository repo,IContentAuditService audit,IContentCacheService cache,IUnitOfWork uow):ICommandHandler<UnpublishContentCommand,Result>{public async Task<Result> HandleAsync(UnpublishContentCommand c,CancellationToken ct=default){var x=await repo.GetByIdWithDetailsAsync(c.Id,ct);if(x is null||x.IsDeleted)return Result.Failure(ContentErrors.ContentNotFound);var before=ContentAuditSnapshots.From(x);x.Unpublish(c.ActorUserId);await audit.PublishAsync(new ContentAuditEvent(ContentAuditEventTypes.ContentUnpublished,ContentAuditActions.StatusChanged,ContentAuditEntityTypes.ContentItem,x.Id,c.ActorUserId,Before:before,After:ContentAuditSnapshots.From(x)),ct);await uow.SaveChangesAsync(ct);await cache.RemoveContentAsync(x.SiteKey,x.Slug,ct);return Result.Success();}}
